def iyilesme(taban, yeni):
    mutlak = taban - yeni
    goreli = mutlak / taban * 100.0
    hizlanma = taban / yeni
    return round(mutlak, 3), round(goreli, 2), round(hizlanma, 4)


def amdahl(p, s):
    return round(1.0 / ((1.0 - p) + p / s), 4)


for t, y in ((12.20, 11.60), (8.00, 6.40)):
    m, g, h = iyilesme(t, y)
    print("taban", t, "yeni", y, "-> mutlak", m, "goreli %", g, "hizlanma", h)

print("amdahl p=0.4 s=3:", amdahl(0.40, 3))
print("amdahl p=0.4 s=1000:", amdahl(0.40, 1000))
print("ust sinir:", round(1.0 / (1.0 - 0.40), 4))

def ga_genisligi(s, n, z=1.96):
    return round(2.0 * z * s / (n ** 0.5), 4)


s = 0.60
for n in (5, 10, 20, 40, 80):
    print("n =", n, "-> GA genisligi =", ga_genisligi(s, n))

print("n=10 / n=40 orani:", round(ga_genisligi(s, 10) / ga_genisligi(s, 40), 4))
